def main():
 local=json.load(open(R/'LOCAL_COMPONENT_TRAIN_VALIDATION.json'));cal=json.load(open(R/'TORSION_CALIBRATION.json'));grad=json.load(open(R/'GRADIENT_DIAGNOSTICS.json'));proto=json.load(open(R/'TRAIN_ONLY_CORRECTION_PROTOTYPES.json'));tail=json.load(open(R/'TORSION_TAIL_SEAM_SENSITIVITY.json'));unc=json.load(open(R/'PAIRED_COMPONENT_UNCERTAINTY.json'))
